<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import TypographyPanel from '../presentation/TypographyPanel.vue'
import AppearancePreviews from '../ui/AppearancePreviews.vue'
import {rememberAppearance,appearanceEpoch,previewAppearance as publishAppearancePreview,cancelAppearancePreview} from '../ui/theme'
import {newId} from '../ids'
import TextEditor from './TextEditor.vue'
import { ref,computed,onMounted,onUnmounted,watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { request } from '../api'
import ColorEditor from './ColorEditor.vue'
import {resolvedStyle,clearColors,type ColorMode} from './colors'
import BlogView from './BlogView.vue'
import { clone } from '../admin/types'
import { styles,palettes,layouts,type Appearance,type Home,type Section,type Nav,type Module } from './types'
const tab=ref<'sections'|'navigation'|'layout'|'appearance'|'text'>('sections'),busy=ref(false),error=ref(''),notice=ref('')
const sections=ref<Section[]>([]),types=ref<any[]>([]),records=ref<any[]>([]),media=ref<any[]>([]),mediaSearch=ref(''),search=ref('')
const section=ref<any>(null),nav=ref<{revision:number;items:Nav[]}>({revision:0,items:[]}),layout=ref<Home>({title:'',description:'',modules:[],revision:0}),appearance=ref<Appearance>({theme:'celadon',mode:'system',revision:0}),previewPath=ref('/')
const textEditor=ref<{canLeave:()=>boolean|Promise<boolean>;isDirty:()=>boolean}|null>(null)
const colorInvalid=ref(false),colorReset=ref(0),previewMode=ref<'follow'|ColorMode>('follow')
const previewAppearance=computed(()=>({...appearance.value,mode:previewMode.value==='follow'?appearance.value.mode:previewMode.value}))
const appearanceOwner=Symbol('site-appearance')
watch([tab,previewAppearance],()=>{if(tab.value==='appearance')publishAppearancePreview(appearanceOwner,previewAppearance.value);else cancelAppearancePreview(appearanceOwner)},{deep:true})
function chooseStyle(style:import('./types').Style){appearance.value={...appearance.value,style}}
function choosePalette(palette:import('./types').PaletteName){appearance.value={...appearance.value,style:resolvedStyle(appearance.value),palette}}
const saved=ref(''),savedAppearance=ref<Appearance>(clone(appearance.value));let alive=true
const snapshot=()=>JSON.stringify(tab.value==='sections'?section.value:tab.value==='navigation'?nav.value:tab.value==='layout'?layout.value:appearance.value)
const dirty=computed(()=>snapshot()!==saved.value||tab.value==='appearance'&&colorInvalid.value)
async function leave(){if(tab.value==='text')return await textEditor.value?.canLeave()??true;return !busy.value&&(!dirty.value||await confirmAction('有未保存的站点配置，确定放弃吗？'))}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){if(alive)error.value=String(e)}finally{if(alive)busy.value=false}}
async function load(){const epoch=appearanceEpoch();colorReset.value++;colorInvalid.value=false;previewMode.value='follow';const [s,t,n,l,a,m]=await Promise.all([request('/admin/blog/sections'),request('/admin/content/types'),request('/admin/blog/navigation'),request('/admin/blog/layout'),request('/admin/blog/appearance'),request('/admin/archive/media?page_size=100')]);if(!alive)return;sections.value=s;types.value=t;nav.value=n;layout.value=l;appearance.value=a;rememberAppearance(a,epoch);savedAppearance.value=clone(a);media.value=m.items;section.value=null;await findRecords();saved.value=snapshot()}
async function findMedia(){const data=await request('/admin/archive/media?page_size=100&q='+encodeURIComponent(mediaSearch.value));const map=new Map(media.value.map(x=>[x.id,x]));for(const m of data.items)map.set(m.id,m);media.value=Array.from(map.values())}
async function findRecords(){const r=await request('/admin/content/records?page_size=100&q='+encodeURIComponent(search.value));const map=new Map(records.value.map(x=>[x.id,x]));for(const x of r.items)map.set(x.id,x);records.value=Array.from(map.values())}
async function switchTab(value:typeof tab.value){if(value===tab.value||!await leave())return;tab.value=value;section.value=null;await run(load)}
async function newSection(){if(!await leave())return;section.value={name:'',slug:'',description:'',cover_id:null,position:sections.value.length,active:true,layout:'grid2',type_ids:[]};saved.value=snapshot()}
async function selectSection(s:Section){if(!await leave())return;section.value=clone(s);saved.value=snapshot()}
async function saveSection(){const s=section.value;if(!s)return;await run(async()=>{const {id,revision,...value}=s;const result=await request('/admin/blog/sections'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify({...value,...(id?{expected_revision:revision}:{})})});section.value=result;sections.value=await request('/admin/blog/sections');saved.value=snapshot();notice.value='栏目已保存'})}
async function save(which:'navigation'|'layout'|'appearance'){if(which==='appearance'&&colorInvalid.value)return;await run(async()=>{const source=which==='navigation'?nav.value:which==='layout'?layout.value:appearance.value;const {revision,...value}=source;const result=await request('/admin/blog/'+which,{method:'PUT',body:JSON.stringify({...value,expected_revision:revision})});if(which==='navigation')nav.value=result;else if(which==='layout')layout.value=result;else{appearance.value=result;rememberAppearance(result);savedAppearance.value=clone(result)}saved.value=snapshot();notice.value='配置已保存，已正式生效'})}
function newNav(){nav.value.items.push({id:newId(),name:'',kind:'home',parent_id:null,section_id:null,record_id:null,page:null,active:true})}
function changeTarget(n:Nav){n.section_id=null;n.record_id=null;n.page=null;if(n.kind==='section')n.section_id=sections.value[0]?.id||null;if(n.kind==='record')n.record_id=records.value[0]?.id||null;if(n.kind==='page')n.page='sections'}
function removeNav(id:string){nav.value.items=nav.value.items.filter(n=>n.id!==id&&n.parent_id!==id)}
function move(list:any[],i:number,d:number){const j=i+d;if(j<0||j>=list.length)return;const row=list.splice(i,1)[0];list.splice(j,0,row)}
function newModule(){layout.value.modules.push({id:newId(),kind:'latest',horizon:30,show_countdown:true,show_years:true,enabled:true,title:'新的故事',text:'',count:6,layout:'grid2',section_id:null,type_id:null,record_ids:[]})}
function defaultTheme(){appearance.value=clearColors({...appearance.value,style:'modern-soft',palette:'celadon',mode:'system'});colorReset.value++;colorInvalid.value=false}
function cancelTheme(){appearance.value=clone(savedAppearance.value);colorReset.value++;colorInvalid.value=false;previewMode.value='follow';saved.value=snapshot()}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||textEditor.value?.isDirty()){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>await leave());onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);void run(load)});onUnmounted(()=>{cancelAppearancePreview(appearanceOwner);alive=false;window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><main class="container site-admin"><header><div><span class="eyebrow">PRIVATE PUBLICATION STUDIO</span><h1>编辑生活杂志</h1></div><div class="actions"><RouterLink to="/">查看私人Blog</RouterLink><RouterLink to="/admin/content">内容与媒体后台</RouterLink></div></header><p>内容、栏目、首页布局和主题各自独立。预览不会自动改变正式配置。</p><nav class="admin-tabs" aria-label="站点管理"><button :class="{quiet:tab!=='sections'}" :disabled="busy" @click="switchTab('sections')">栏目管理</button><button :class="{quiet:tab!=='navigation'}" :disabled="busy" @click="switchTab('navigation')">导航管理</button><button :class="{quiet:tab!=='layout'}" :disabled="busy" @click="switchTab('layout')">首页模块</button><button :class="{quiet:tab!=='appearance'}" :disabled="busy" @click="switchTab('appearance')">外观设置</button><button :class="{quiet:tab!=='text'}" :disabled="busy" @click="switchTab('text')">文字自定义</button></nav><p v-if="error" class="error" role="alert">{{error}}（未保存输入会保留。）</p><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理…</p>
<div v-if="tab==='sections'" class="admin-layout"><aside class="card"><h2>Blog栏目</h2><button :disabled="busy" @click="newSection">新建栏目</button><button v-for="s in sections" :key="s.id" class="entry" :disabled="busy" @click="selectSection(s)">{{s.name}} · {{s.active?'启用':'停用'}}</button></aside><article class="card"><form v-if="section" @submit.prevent="saveSection"><fieldset :disabled="busy"><label>栏目名称<input v-model="section.name" required maxlength="100" /></label><label>栏目标识<input aria-label="栏目标识" v-model="section.slug" :disabled="!!section.id" required pattern="[a-z][a-z0-9_-]{0,79}" /><small>创建后保持不变，改名不会破坏旧链接。</small></label><label>栏目简介<textarea v-model="section.description" maxlength="10000" /></label><label>搜索媒体库封面<input v-model="mediaSearch" maxlength="200" type="search" /></label><button type="button" class="quiet" @click="run(findMedia)">查找待选封面</button><label>栏目封面<select v-model="section.cover_id" aria-label="栏目封面"><option :value="null">不设置封面</option><option v-if="section.cover_id&&!media.some(m=>m.id===section.cover_id)" :value="section.cover_id">当前封面（未在搜索结果内）</option><option v-for="m in media" :key="m.id" :value="m.id">{{m.title||m.filename}}</option></select></label><label>栏目顺序<input v-model.number="section.position" type="number" min="0" max="10000" /></label><label>栏目列表布局<select v-model="section.layout" aria-label="栏目列表布局"><option v-for="(name,key) in layouts" :key="key" :value="key">{{name}}</option></select></label><label class="checks"><input v-model="section.active" type="checkbox" /> 启用栏目（停用保留内容）</label><fieldset><legend>绑定内容类型（可多选，也可在其他栏目复用）</legend><label v-for="t in types" :key="t.id" class="checks"><input v-model="section.type_ids" type="checkbox" :value="t.id" />{{t.name}}</label></fieldset><button>保存栏目</button></fieldset></form><p v-else class="muted">自由建立栏目，再将一个或多个内容类型绑定到它。</p></article></div>
<section v-else-if="tab==='navigation'" class="card"><h2>两级站内导航</h2><p class="muted">删除父导航同时移除其子项；内容与栏目不会删除。不允许外部地址。</p><div v-for="(n,i) in nav.items" :key="n.id" class="field-config"><fieldset :disabled="busy"><label>导航名称<input v-model="n.name" required maxlength="100" /></label><div class="editor-meta"><label>导航目标<select v-model="n.kind" aria-label="导航目标" @change="changeTarget(n)"><option value="home">首页</option><option value="section">栏目</option><option value="record">动态文章</option><option value="page">已有页面</option></select></label><label>父导航<select v-model="n.parent_id" aria-label="父导航"><option :value="null">顶级导航</option><option v-for="parent in nav.items.filter(p=>!p.parent_id&&p.id!==n.id)" :key="parent.id" :value="parent.id">{{parent.name||'未命名导航'}}</option></select></label></div><label v-if="n.kind==='section'">目标栏目<select v-model="n.section_id" aria-label="目标栏目"><option v-for="s in sections" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label v-if="n.kind==='record'">目标文章<select v-model="n.record_id" aria-label="目标文章"><option v-for="r in records" :key="r.id" :value="r.id">{{r.title}}</option></select></label><label v-if="n.kind==='page'">站内页面<select v-model="n.page" aria-label="站内页面"><option value="sections">所有栏目</option><option value="about">关于本站</option><option value="stories">所有故事</option><option value="trips">旅行</option><option value="food">美食足迹</option><option value="places">地点足迹</option><option value="movies">观影记录</option><option value="shows">演出记录</option><option value="gifts">礼物记录</option><option value="transport">交通足迹</option><option value="photos">生活相册</option><option value="calendar">纪念日历</option><option v-if="n.page==='journals'" value="journals" disabled>兼容入口（现跳转全部故事）</option></select></label><label class="checks"><input v-model="n.active" type="checkbox" />显示导航</label><div class="actions"><button class="quiet" :disabled="i===0" @click="move(nav.items,i,-1)">导航上移</button><button class="quiet" :disabled="i===nav.items.length-1" @click="move(nav.items,i,1)">导航下移</button><button class="quiet" @click="removeNav(n.id)">移除导航</button></div></fieldset></div><div class="actions"><button class="quiet" :disabled="busy||nav.items.length>=50" @click="newNav">添加导航</button><button :disabled="busy" @click="save('navigation')">保存导航</button></div></section>
<section v-else-if="tab==='layout'" class="card"><h2>首页模块管理</h2><fieldset :disabled="busy"><p>网站名称在“文字自定义”中统一编辑。</p><label>网站简介<textarea v-model="layout.description" maxlength="2000" /></label><div v-for="(m,i) in layout.modules" :key="m.id" class="field-config module-config"><div class="actions"><strong>模块 {{i+1}}</strong><button class="quiet" :disabled="i===0" @click="move(layout.modules,i,-1)">模块上移</button><button class="quiet" :disabled="i===layout.modules.length-1" @click="move(layout.modules,i,1)">模块下移</button><button class="quiet" @click="layout.modules.splice(i,1)">移除模块</button></div><label>记录模式（与内容类型独立）<select aria-label="首页模块记录模式" v-model="m.record_mode"><option :value="null">全部模式</option><option value="daily">日常记录</option><option value="travel">旅行记录</option></select></label><label class="checks"><input v-model="m.enabled" type="checkbox" />启用模块</label><div class="editor-meta"><label>模块种类<select v-model="m.kind" aria-label="模块种类"><option value="hero">Hero · 网站介绍</option><option value="featured">Featured · 精选记录</option><option value="latest">Latest · 最近发布</option><option value="section">Section · 指定栏目</option><option value="gallery">Gallery · 图片精选</option><option value="text">Text · 自定义文字</option><option value="anniversary_calendar">重要日子 · 纪念日历</option></select></label><label>模块布局<select v-model="m.layout" aria-label="模块布局"><option v-for="(label,key) in layouts" :key="key" :value="key">{{label}}</option></select></label></div><label>模块标题<input v-model="m.title" maxlength="200" /></label><label v-if="m.kind==='hero'||m.kind==='text'">模块文字（安全Markdown）<textarea v-model="m.text" maxlength="10000" rows="4" /></label><template v-else><label>展示数量<input v-model.number="m.count" type="number" min="1" max="24" /></label><template v-if="m.kind==='anniversary_calendar'"><label>预告范围（天）<input v-model.number="m.horizon" type="number" min="0" max="366"/></label><label><input v-model="m.show_countdown" type="checkbox"/>显示倒计时</label><label><input v-model="m.show_years" type="checkbox"/>显示周年数</label></template><label v-else>模块栏目<select v-model="m.section_id" aria-label="模块栏目"><option :value="null">全部栏目</option><option v-for="s in sections" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>模块内容类型<select v-model="m.type_id" aria-label="模块内容类型"><option :value="null">全部类型</option><option v-for="t in types" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label v-if="m.kind==='featured'||m.kind==='gallery'">精选文章（可多选）<select v-model="m.record_ids" multiple aria-label="精选文章"><option v-for="r in records" :key="r.id" :value="r.id">{{r.title}} · {{r.status==='published'?'已发布':'草稿，前台会跳过'}}</option><option v-for="id in m.record_ids.filter(id=>!records.some(r=>r.id===id))" :key="id" :value="id">失效或未加载的已选文章（可取消选择）</option></select></label></template></div><div class="actions"><button class="quiet" :disabled="layout.modules.length>=30" @click="newModule">添加首页模块</button><button @click="save('layout')">保存首页布局</button></div></fieldset></section>
<section v-else-if="tab==='appearance'"><div class="card"><h2>外观设置</h2><TypographyPanel /><p>临时预览同步当前页面及下方真实组件，点击保存后才持久化全站外观。不会改动文章、栏目或模块。</p><fieldset :disabled="busy"><fieldset class="appearance-dimension"><legend>1 · 风格 Style</legend><div class="theme-choices"><label v-for="(name,key) in styles" :key="key" class="style-choice"><input type="radio" name="style" :value="key" :checked="resolvedStyle(appearance)===key" @change="chooseStyle(key)" />{{name}}<small>{{key==='modern-flat'?'利落边界、低圆角、扁平表面':key==='editorial'?'衬线层级、杂志留白、直线分隔':key==='modern-soft'?'柔和圆角、轻阴影、舒适层次':'半透明表面、磨砂背景、轻盈叠层'}}</small></label></div></fieldset><fieldset class="appearance-dimension"><legend>2 · 主题配色 Palette</legend><p v-if="!appearance.palette" class="legacy-palette-note">当前保留历史配色原貌。切换风格不会更换这些颜色；明确选择下列配色后才启用新色阶，历史颜色仍保留。</p><div class="theme-choices"><label v-for="(name,key) in palettes" :key="key" class="palette-choice theme-choice" :data-swatch="key==='lilac'?'soft':'celadon'"><input type="radio" name="palette" :value="key" :checked="appearance.palette===key" @change="choosePalette(key)" />{{name}}<span class="theme-palette" aria-hidden="true"><i/><i/><i/><i/><i/></span></label></div></fieldset><p><RouterLink to="/admin/appearance-lab">只读视觉实验室 · 比较候选方案（不保存）</RouterLink></p><label>配色模式<select v-model="appearance.mode" aria-label="配色模式"><option value="light">浅色</option><option value="dark">深色</option><option value="system">跟随系统</option></select></label><ColorEditor :appearance="appearance" :preview-mode="previewMode" :reset-key="colorReset" @update="appearance=$event" @preview="previewMode=$event" @invalid="colorInvalid=$event" /><p role="status">{{dirty?'有未保存的外观修改；下方仅为预览。':'当前显示已保存的外观配置。'}}</p><div class="actions"><button :disabled="colorInvalid" @click="save('appearance')">保存外观</button><button class="quiet" @click="cancelTheme">取消外观修改</button><button class="quiet" @click="defaultTheme">恢复默认主题（待保存）</button></div><p class="muted">恢复默认主题会选择 Modern Soft / 晨雾青瓷 / 跟随系统，仅清除此组合的覆盖；其他组合及历史颜色保留，保存前可取消。</p></fieldset></div><section class="preview-panel"><div class="card"><h3>真实Blog预览（未保存）</h3><label>预览页面<select v-model="previewPath" aria-label="预览页面"><option value="/">Blog首页</option><option value="/sections">栏目列表</option><option value="/timeline">生活时间线</option><option :value="'/year-review/'+new Date().getFullYear()">年度回顾</option><option v-for="s in sections.filter(s=>s.active)" :key="s.id" :value="'/sections/'+s.slug">{{s.name}}</option><option v-for="r in records.filter(r=>r.status==='published')" :key="r.id" :value="'/posts/'+r.id">{{r.title}}</option></select></label></div><AppearancePreviews :appearance="previewAppearance" :record-id="records[0]?.id"><BlogView embedded :preview="previewAppearance" :target="previewPath" @navigate="previewPath=$event" /></AppearancePreviews></section></section>
<section v-if="tab==='navigation'||tab==='layout'" class="card record-search"><label>搜索待选文章<input v-model="search" maxlength="200" type="search" /></label><button :disabled="busy" @click="run(findRecords)">查找待选文章</button></section><p v-if="dirty" class="muted">有未保存的配置。</p><button v-if="tab!=='text'" class="quiet" :disabled="busy" @click="async()=>{if(await leave())await run(load)}">重新读取已保存配置</button><TextEditor v-if="tab==='text'" ref="textEditor" /></main></template>
